package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.io.Base64Variant;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.BooleanNode;
import com.fasterxml.jackson.databind.node.IntNode;
import com.fasterxml.jackson.databind.node.NullNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.node.POJONode;
import com.fasterxml.jackson.databind.node.TextNode;
import com.fasterxml.jackson.databind.node.TreeNode;
import com.fasterxml.jackson.databind.node.TreeTraversingParser;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TreeTraversingParser_getBinaryValue_TriageGen1Test {

    private ObjectMapper mapper;
    private Base64Variant variant;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        variant = Base64Variant.of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/");
    }

    @Test
    public void testGetBinaryValue_NullNode() throws IOException, JsonParseException {
        // currentNode() returns null
        TreeTraversingParser parser = new TreeTraversingParser(null);
        byte[] result = parser.getBinaryValue(variant);
        Assert.assertNull(result);
    }

    @Test
    public void testGetBinaryValue_TextNodeWithBinaryData() throws IOException, JsonParseException {
        // n.binaryValue() works for TextNode (Base64 encoded string)
        byte[] expected = new byte[]{1, 2, 3, 4};
        String base64 = java.util.Base64.getEncoder().encodeToString(expected);
        TextNode textNode = mapper.getNodeFactory().textNode(base64);

        TreeTraversingParser parser = new TreeTraversingParser(textNode);
        byte[] result = parser.getBinaryValue(variant);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testGetBinaryValue_BinaryNode() throws IOException, JsonParseException {
        // n.binaryValue() works for real binary nodes (if supported by implementation/codec)
        // In Jackson, we can simulate this via a specialized node or if the parser treats it as such.
        // Using a text node that is valid base64 is the most reliable way to trigger n.binaryValue() != null
        byte[] expected = new byte[]{(byte) 0xFF, (byte) 0x00};
        String base64 = java.util.Base64.getEncoder().encodeToString(expected);
        TextNode textNode = mapper.getNodeFactory().textNode(base64);

        TreeTraversingParser parser = new TreeTraversingParser(textNode);
        byte[] result = parser.getBinaryValue(variant);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testGetBinaryValue_PojoNodeWithByteArray() throws IOException, JsonParseException {
        // n.isPojo() is true, and ((POJONode) n).getPojo() is byte[]
        byte[] expected = new byte[]{10, 20, 30};
        POJONode pojoNode = new POJONode(expected);

        TreeTraversingParser parser = new TreeTraversingParser(pojoNode);
        byte[] result = parser.getBinaryValue(variant);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testGetBinaryValue_PojoNodeWithNonByteArray() throws IOException, JsonParseException {
        // n.isPojo() is true, but getPojo() is not byte[]
        POJONode pojoNode = new POJONode("not a byte array");

        TreeTraversingParser parser = new TreeTraversingParser(pojoNode);
        byte[] result = parser.getBinaryValue(variant);

        Assert.assertNull(result);
    }

    @Test
    public void testGetBinaryValue_OtherNodes_ReturnsNull() throws IOException, JsonParseException {
        // Test with IntNode, BooleanNode, etc. where n.binaryValue() is null and n.isPojo() is false
        IntNode intNode = mapper.getNodeFactory().numberNode(123);
        TreeTraversingParser parserInt = new TreeTraversingParser(intNode);
        Assert.assertNull(parserInt.getBinaryValue(variant));

        BooleanNode boolNode = mapper.getNodeFactory().booleanNode(true);
        TreeTraversingParser parserBool = new TreeTraversingParser(boolNode);
        Assert.assertNull(parserBool.getBinaryValue(variant));

        NullNode nullNode = mapper.getNodeFactory().nullNode();
        TreeTraversingParser parserNull = new TreeTraversingParser(nullNode);
        Assert.assertNull(parserNull.getBinaryValue(variant));
    }

    @Test
    public void testGetBinaryValue_TextNodeEmpty() throws IOException, JsonParseException {
        // TextNode exists, but n.binaryValue() might return null or empty
        // If n.binaryValue() returns null, it should proceed to check isPojo
        TextNode emptyTextNode = mapper.getNodeFactory().textNode("");
        // Note: n.binaryValue() on an empty text node usually returns empty byte array, not null.
        // To force the n.binaryValue() == null branch, we'd need a node where binaryValue returns null.
        // In Jackson, most nodes return null for binaryValue() if not applicable.

        // We use a node that is not a TextNode to ensure binaryValue() returns null
        ArrayNode arrayNode = mapper.getNodeFactory().arrayNode();
        TreeTraversingParser parser = new TreeTraversingParser(arrayNode);

        byte[] result = parser.getBinaryValue(variant);
        Assert.assertNull(result);
    }
}
